/**
 * generate-audio.ts
 * Creates 6 minimal valid MP3 placeholder files in public/audio/
 * Each file is a single MPEG-1 Layer 3 frame (silence, 128kbps, 44100Hz, Joint Stereo).
 * Browsers will load and play these without errors.
 */

import { mkdirSync, writeFileSync } from "fs";
import { join, dirname } from "path";

const OUT_DIR = join(import.meta.dir, "..", "public", "audio");

// Hex string of a single valid MPEG1 Layer3 silent frame (417 bytes)
const MP3_HEX =
  "";

// Parse hex string to Uint8Array
function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  }
  return bytes;
}

const FILES = [
  "ding-dong.mp3",
  "phrase_destination.mp3",
  "phrase_retard.mp3",
  "phrase_minutes.mp3",
  "rappel_bagages.mp3",
  "rappel_valeurs.mp3",
];

async function main() {
  // Ensure output directory exists
  mkdirSync(OUT_DIR, { recursive: true });

  // Generate the valid silent MP3 bytes
  const mp3Bytes = hexToBytes(MP3_HEX);

  console.log(`Generated ${mp3Bytes.length} bytes of valid MP3 data`);
  console.log(`First 4 bytes: ${mp3Bytes[0].toString(16).padStart(2, "0")} ${mp3Bytes[1].toString(16).padStart(2, "0")} ${mp3Bytes[2].toString(16).padStart(2, "0")} ${mp3Bytes[3].toString(16).padStart(2, "0")}`);

  for (const file of FILES) {
    const filePath = join(OUT_DIR, file);
    writeFileSync(filePath, mp3Bytes);
    console.log(`  Created ${filePath} (${mp3Bytes.length} bytes)`);
  }

  console.log(`\nDone! Created ${FILES.length} placeholder MP3 files in ${OUT_DIR}`);
}

main();
